test('a saved big fish reappears in a shelter that fits it', () => {
  for (const r of [3, 8, 14, 20, 25]) {
    const g = createGame({ seed: 1, r, spawning: false })
    const sh = g.world.shelters.find((s) => s.id === g.player.lastShelter)
    assert.ok(sh.cap >= r || sh.cap === Math.max(...g.world.shelters.map((x) => x.cap)), `r=${r} placed in a cap ${sh.cap} shelter`)
    step(g, { ax: 0, ay: 0 }, 1 / 60)
    if (sh.cap >= r) assert.equal(g.player.hidden, true, `r=${r} should start hidden`)
  }
})

